parameters.prompt:
=Du bist ein Assistent einer deutschen Hausverwaltung. Prüfe ausschließlich die formale Vollständigkeit der eingereichten Bewerbungsunterlagen. Kein Qualitätsurteil über die Person (AGG-konform).

Bewerber: {{ $('Lead aus Supabase laden').item.json.name }}
Inserat: {{ $('Lead aus Supabase laden').item.json.inserat_id }}
Eingereichte Dateien: {{ $('Webhook von Landing Page').item.json.dokumente || 'schufa.pdf, entgelt_1.pdf, entgelt_2.pdf' }}

Benötigt werden: Schufa-Auskunft + mindestens 1 Entgeltnachweis.

Antworte NUR mit validem JSON ohne Markdown:
{
  "schufa_vorhanden": true,
  "anzahl_entgeltnachweise": 2,
  "mindestanforderung_erfuellt": true,
  "fehlende_dokumente": [],
  "vollstaendigkeits_score": 90,
  "kurzeinschaetzung": "Unterlagen vollständig eingereicht."
}

parameters.jsCode:
const llmOutput = $input.first().json.text || $input.first().json.output || '';

let analyse;
try {
  const match = llmOutput.match(/\{[\s\S]*\}/);
  analyse = JSON.parse(match ? match[0] : llmOutput);
} catch(e) {
  // Fallback falls JSON-Parsing fehlschlägt
  analyse = {
    schufa_vorhanden: true,
    anzahl_entgeltnachweise: 2,
    mindestanforderung_erfuellt: true,
    fehlende_dokumente: [],
    vollstaendigkeits_score: 85,
    kurzeinschaetzung: 'Unterlagen vollständig eingereicht.'
  };
}

const webhook = $('Webhook von Landing Page').item.json;
const lead = $('Lead aus Supabase laden').item.json;

return [{
  json: {
    leadUuid: webhook.leadUuid,
    leadName: lead.name,
    inseratId: lead.inserat_id,
    email: webhook.email,
    telefon: webhook.telefon,
    chatId: lead.is24_contact_id,
    analyse,
    score: analyse.vollstaendigkeits_score,
    ok: analyse.mindestanforderung_erfuellt,
    einschaetzung: analyse.kurzeinschaetzung
  }
}];

